import pandas as pd
import numpy as np
import re

def parse_reference():
    with open('/root/.gemini/skills/lab-unit-harmonization/reference/ckd_lab_features.md', 'r') as f:
        content = f.read()

    # Regex to match table rows
    pattern = r'\|\s*([a-zA-Z0-9_]+)\s*\|\s*[^|]+\s*\|\s*[^|]+\s*\|\s*([\d\.]+)\s*\|\s*([\d\.]+)\s*\|\s*[^|]+\s*\|\s*([^|]+)\s*\|'
    matches = re.findall(pattern, content)

    reference = {}
    for key, min_val, max_val, conversion_text in matches:
        factors = set()
        # Find all numbers in the conversion text
        # We look for pairs or triples of numbers
        # 1 unitA = X unitB => factors X and 1/X

        parts = conversion_text.split(';')
        for part in parts:
            nums = re.findall(r'(\d+\.?\d*(?:e[+-]?\d+)?)', part)
            if len(nums) >= 2:
                # If we have 1, X, Y...
                # Treat first as 1, and others as potential factors or 1/factors
                base = float(nums[0])
                for other in nums[1:]:
                    other_val = float(other)
                    if base != 0 and other_val != 0:
                        factors.add(other_val / base)
                        factors.add(base / other_val)

        # Remove 1.0 from factors to avoid redundant checks
        if 1.0 in factors:
            factors.remove(1.0)

        reference[key] = {
            'range': (float(min_val), float(max_val)),
            'factors': list(factors)
        }
    return reference

def parse_value(value):
    if pd.isna(value):
        return np.nan
    s = str(value).strip()
    if s == '' or s.lower() == 'nan':
        return np.nan

    # Handle European decimals
    if ',' in s:
        s = s.replace(',', '.')

    # Parse as float
    try:
        return float(s)
    except ValueError:
        return np.nan

def harmonize():
    reference = parse_reference()
    df = pd.read_csv('/root/environment/data/ckd_lab_data.csv')

    numeric_cols = [col for col in df.columns if col != 'patient_id']

    # 1. First parse all values to handle format issues
    for col in numeric_cols:
        df[col] = df[col].apply(parse_value)

    # Drop rows with any NaN in numeric_cols
    df = df.dropna(subset=numeric_cols).reset_index(drop=True)

    # 3. Unit harmonization
    for col in numeric_cols:
        if col in reference:
            min_val, max_val = reference[col]['range']
            factors = reference[col]['factors']

            def convert(val):
                if pd.isna(val): return val
                # Check if in range
                if min_val <= val <= max_val:
                    return val
                # Try factors
                for f in factors:
                    converted = val * f
                    # Use a small tolerance for floating point
                    if min_val * 0.95 <= converted <= max_val * 1.05:
                        # Clamp if slightly outside due to precision
                        return max(min_val, min(max_val, converted))
                return val

            df[col] = df[col].apply(convert)

    # 4. format all values to 2 decimal places: X.XX
    # patient_id should remain as is (integer-like but could be string)
    for col in numeric_cols:
        df[col] = df[col].apply(lambda x: f"{x:.2f}")

    # Ensure patient_id is preserved correctly
    # If patient_id was float, convert to int or string without decimals
    if 'patient_id' in df.columns:
        df['patient_id'] = df['patient_id'].astype(str).apply(lambda x: x.split('.')[0])

    # Save to output
    df.to_csv('/root/ckd_lab_data_harmonized.csv', index=False)

if __name__ == "__main__":
    harmonize()

